inline constexpr int kOrientations = 4;
inline constexpr int kColumns = study_grid::Grid::kColumns;

static_assert(kColumns > 0, "grid must have at least one column");
static_assert(kColumns <= INT_MAX / kOrientations,
              "kColumns * kOrientations would overflow int");

inline constexpr int kCount = kColumns * kOrientations;

// Quarter-turn orientations are labels, not shapes: geometrically duplicate
// shapes keep distinct orientation labels and remain separate actions.
struct Target {
  int column;
  int quarter;
};

inline constexpr std::optional<int> encode(int column, int quarter) noexcept {
  if (column < 0 || quarter < 0) {
    return std::nullopt;
  }
  if (column >= kColumns || quarter >= kOrientations) {
    return std::nullopt;
  }
  return column * kOrientations + quarter;
}

inline constexpr std::optional<Target> decode(int action) noexcept {
  if (action < 0 || action >= kCount) {
    return std::nullopt;
  }
  return Target{action / kOrientations, action % kOrientations};
}

struct Plan {
    study_round::Round result;
    std::vector<study_input::Mask> inputs;
};

// This route family rotates clockwise, translates, then drops. It is not BFS
// over every reachable placement. Each input consumes a real Round tick.
inline std::optional<Plan> plan(const study_round::Round& start, int action) {
    const auto target=decode(action);
    if(!target || start.finished() || !start.active())return std::nullopt;
    Plan candidate{start,{}};
    auto tick=[&](study_input::Mask mask) {
        const auto intent=*study_input::decode(mask);
        const auto result=candidate.result.tick(intent.horizontal,intent.clockwise,
                                                intent.soft_drop,intent.hard_drop);
        candidate.inputs.push_back(mask);
        return result;
    };
    const auto continued=[](study_round::Step step) {
        return step==study_round::Step::waiting || step==study_round::Step::changed;
    };

const int turns=(target->quarter-start.quarter()+kOrientations)%kOrientations;
for(int i=0;i<turns;++i) {
    const int expected=(candidate.result.quarter()+1)%kOrientations;
    if(!continued(tick(study_input::rotate)) || candidate.result.quarter()!=expected)
        return std::nullopt; // Blocked rotation or a lock before the intended drop.
}
// Rotation kicks may change the origin: derive translation from that result.
while(candidate.result.active()->origin.column!=target->column) {
    const int before=candidate.result.active()->origin.column;
    const int direction=before<target->column?1:-1;
    if(!continued(tick(direction>0?study_input::right:study_input::left)) ||
       candidate.result.active()->origin.column!=before+direction)
        return std::nullopt;
}

    const auto last=tick(study_input::drop);
    if(last!=study_round::Step::locked && last!=study_round::Step::game_over)
        return std::nullopt;
    return candidate;
}

inline std::vector<int> legal_actions(const study_round::Round& round) {
    std::vector<int> actions;
    for(int action=0;action<kCount;++action)
        if(plan(round,action))actions.push_back(action);
    return actions;
}

std::vector<int> legal_actions() const { return study_actions::legal_actions(round_); }
std::vector<study_input::Mask> action_trace(int action) const {
    const auto selected=study_actions::plan(round_,action);
    if(!selected)throw std::invalid_argument("action has no route from this state");
    return selected->inputs;
}
struct ActionResult { std::size_t ticks; int lines; bool ended; };
ActionResult apply_action(int action) {
    const auto selected=study_actions::plan(round_,action);
    if(!selected)throw std::invalid_argument("action has no route from this state");
    round_=selected->result;
    return {selected->inputs.size(),round_.last_cleared(),round_.finished()};
}

def decode(action,schema):
    columns,orientations=dimensions(schema)
    action=integer(action)
    if not 0 <= action < columns*orientations:
        raise ValueError("action outside domain")
    return divmod(action,orientations)


def legal_mask(session,schema):
    columns,orientations=dimensions(schema)
    mask=np.zeros(columns*orientations,dtype=np.bool_)
    for action in session.legal_actions():
        decode(action,schema)  # Do not allow a negative Python index to alias the end.
        mask[action]=True
    return mask

def masked_log_softmax(logits,mask):
    import torch
    if not logits.is_floating_point() or mask.dtype != torch.bool:
        raise TypeError("floating logits and bool mask required")
    if logits.ndim < 1 or logits.shape[-1] == 0 or logits.shape != mask.shape:
        raise ValueError("matching nonempty action axis required")
    if logits.device != mask.device:
        raise ValueError("same device required")
    if not mask.any(dim=-1).all():
        raise ValueError("no legal action in a row")
    if not torch.isfinite(logits.masked_select(mask)).all():
        raise ValueError("legal logits must be finite")
    logp = torch.log_softmax(logits.masked_fill(~mask,float("-inf")),dim=-1)
    if not torch.isfinite(logp.masked_select(mask)).all():
        raise ValueError("normalized legal log probabilities must be finite")
    return logp

def entropy(logp,mask):
    # Mask the operand before multiplication so the backward graph avoids 0 * -inf.
    safe=logp.masked_fill(~mask,0.0)
    return -(logp.exp()*safe).sum(dim=-1)
